"""Render the same calculated A/B case through PDCA and TRI-V, without altering the book."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'e-book/review/ab_only_methods_v01';r=json.loads((D/'calculated_results.json').read_text(encoding='utf-8'));plan=json.loads((D/'design_fixture.json').read_text(encoding='utf-8'))['plan_in_the_story'];a,b=r['arms'];g=r['exploratory_group_contribution'];p=r['primary'];guard=r['guardrail']
def won(x):return f'{x:+,.0f}원'
def ci(x):return '['+', '.join(f'{v:+,.0f}' for v in x)+']원'
facts=f'''<table><thead><tr><th>같은 30일 결과</th><th>A 쿠폰 없음</th><th>B 1만원 쿠폰</th></tr></thead><tbody><tr><td>전체 배정 고객</td><td>{a['assigned']:,}명</td><td>{b['assigned']:,}명</td></tr><tr><td>서비스 완료 고객</td><td>{a['completed']:,}명 ({a['completed_rate_pct']:.0f}%)</td><td>{b['completed']:,}명 ({b['completed_rate_pct']:.0f}%)</td></tr><tr><td>공헌이익 합계</td><td>{a['total_contribution_KRW']:,}원</td><td>{b['total_contribution_KRW']:,}원</td></tr><tr><td>배정 고객당 공헌이익</td><td>{a['mean_contribution_KRW']:,.0f}원</td><td>{b['mean_contribution_KRW']:,.0f}원</td></tr></tbody></table>'''
groups=f'''<table><thead><tr><th>배정 전 상태</th><th>A 고객당 이익</th><th>B 고객당 이익</th><th>B-A, 탐색 95% 구간</th></tr></thead><tbody><tr><td>당사 서비스 첫 이용 대상</td><td>3,200원</td><td>3,900원</td><td>{won(g['first_service']['effect_B_minus_A_KRW'])}<br>{ci(g['first_service']['ci95_KRW'])}</td></tr><tr><td>당사 서비스 기존 고객</td><td>12,000원</td><td>8,100원</td><td>{won(g['repeat_service']['effect_B_minus_A_KRW'])}<br>{ci(g['repeat_service']['ci95_KRW'])}</td></tr></tbody></table>'''
# Every displayed quantitative result below is formatted from the verified ledger.
cellmap={(x['stratum'],x['arm']):x for x in r['cells']}
for key,val in [('first_service',3200),('repeat_service',12000)]:assert cellmap[(key,'A')]['mean_KRW']==val
for key,val in [('first_service',3900),('repeat_service',8100)]:assert cellmap[(key,'B')]['mean_KRW']==val
pdca=[
{'title':'Plan: A/B로 답할 질문과 성공 조건을 먼저 정한다','body':f'''<p>가설은 “쿠폰 B가 현재 대상의 배정 고객당 30일 공헌이익을 늘린다”다. 방문 건수는 진단 지표이고 주지표는 모든 배정 고객을 분모로 한 공헌이익이다. 첫 이용과 기존 고객은 배정 전에 정의하고 각 상태 안에서 균형 배정한다.</p><p>이 이야기의 확대 후보 조건은 주지표 95% 하한이 +{plan['business_minimum_KRW_per_assigned_customer']:,}원을 넘고 보호와 운영 승인을 충족하는 것이다. 철회 악화 한계는 +{guard['margin_pp']:.2f}pp다. 고정 종료, 개인별 30일 창과 기록 대사를 정한다. 이것은 가상 회사의 예시 정책이지 모든 A/B 테스트의 보편적 승인선이 아니다.</p><p><strong>산출물:</strong> 가설, 대비, 배정과 분석 단위, 지표와 분모, 창과 종료, 가족, 보호 및 경제 기준이 담긴 A/B 실험 계약.</p>''','output':'A/B 실험 계약'},
{'title':'Do: 무작위 배정과 측정의 경로를 보존한다','body':f'''<p>이 합성 사례는 고객 {r['row_count']:,}명, 군당 {a['assigned']:,}명이며 상태와 군의 각 셀은 {r['cells'][0]['n']:,}명이다. 배정 고객 ID는 유일하고 각 고객의 30일 결과를 유지한다. 방문자만 남기거나 전달 실패를 사후 제외하지 않는다.</p><p>고정 카운트로 만든 CSV를 다시 읽고 SQLite 집계와 대조했다. 현실의 원장 감사가 아니라 교육 자료의 무결성 점검이다. 실제 시행에서는 배정 오류, 사건 누락, 다른 캠페인 접촉과 동의 처리를 감시한다. 피해를 막는 관찰과 유리한 p값에서 임의 종료하는 일은 다르다.</p><p><strong>산출물:</strong> 배정 원장, 결과 원장, 품질과 계획 이탈 기록. 본 예제는 실제 기업에서 실행한 결과가 아니다.</p>''','output':'배정과 사건 원장 및 이탈 기록'},
{'title':'Check: 방문의 순위와 실험의 성공을 구별한다','body':facts+f'''<p>이번 표본에서 B 완료는 {r['changes']['additional_completed_B_minus_A']:,}명 더 많다. 그러나 완료율 차이의 탐색 95% 구간은 [{r['exploratory_completed_rate']['ci95_pp'][0]:+.2f}, {r['exploratory_completed_rate']['ci95_pp'][1]:+.2f}]pp로 완료 우위도 확정하지 않는다. 주지표는 애초에 완료율이 아니라 공헌이익이다.</p><p><strong>배정 고객당 공헌이익 차이 {won(p['effect_B_minus_A_KRW'])}, 95% 구간 {ci(p['ci95_KRW'])}.</strong> 정한 비용 모형과 분석 가정 아래 전체 대상 B의 이익 감소를 지지한다. 원가는 고정 교육 가정이지 실제 OEM 장부가 아니다.</p><p>철회 차이는 +{guard['difference_pp']:.2f}pp이고 단측 95% score 상한은 +{guard['one_sided_95_upper_score_pp']:.3f}pp다. 한계 +{guard['margin_pp']:.2f}pp 안의 비열등성도 확인하지 못한다. 안전 통과도 확정 위해도 아니다. 상태별 진단은 다음 가설을 찾는 보조 분석으로 남긴다.</p><p><strong>산출물:</strong> 효과와 불확실성, 사업과 보호, 적용 범위가 분리된 증거 보고서.</p>''','output':'승패와 채택을 분리한 증거 보고서'},
{'title':'Act: 전체 B 확대는 거절하고 다음 실험을 좁힌다','body':f'''<p><strong>현재 대상 전체에 쿠폰 B를 확대하지 않는 것이 이 예제의 제안이다.</strong> 현행 A와 비교해 배정 고객당 이익이 줄고 보호 평가도 통과하지 않았다. 방문 수가 더 많다는 이유로 성공 지표를 바꾸지 않는다.</p><p>첫 이용 대상의 공헌이익 차이 {won(g['first_service']['effect_B_minus_A_KRW'])}는 후속 가설로 남긴다. 그 집단의 탐색 구간 하한은 {won(g['first_service']['ci95_KRW'][0])}로 예시 사업 기준 +{plan['business_minimum_KRW_per_assigned_customer']:,}원까지 확인한 것은 아니다. 사전 상태 정의가 있다는 사실만으로 집단별 확증이 되지도 않는다.</p><p>다음 사이클은 새 첫 이용 대상 코호트에서 A/B를 다시 설계한다. 기획자는 쿠폰 목적과 대상을, 재무는 실제 공헌이익과 추가 비용을, 분석자는 정보량과 비교 가족을, 보호 담당자는 한계와 관측을, 운영자는 용량을 확정한다. 새 결과를 보기 전에 승인받으며 현재 자료로 혼합 정책을 이미 검증했다고 쓰지 않는다.</p><p><strong>산출물:</strong> 전체 B 미확대 제안, 책임과 후속 실험 계약. 실제 승인이나 발송을 수행한 것은 아니다.</p>''','output':'현재 정책 결정과 다음 실험 계약'}]
triv=[
{'title':'V1: A와 B는 정확히 무엇을 비교했는가?','body':f'''<p class="muted">Variable Control / 모든 변수를 완벽하게 통제한다는 뜻이 아니라, A/B의 대비와 배정 및 측정을 명확히 고정합니다.</p><p><strong>“쿠폰 동봉 정책”과 “쿠폰 없는 같은 안내 정책”을 비교했다.</strong> 미발송군이 없으므로 연락 자체의 증분 효과를 추정한 것이 아니다. 고객을 배정하고 결과도 고객별로 읽는다. 첫 이용과 기존 고객의 비율을 고정했으므로 그 표적 구성의 평균차를 추정한다.</p><p>개인별 30일 창, 배정 전체 분모와 원장 대사를 유지했다는 교육용 전제에서 비교를 읽는다. 공헌이익은 완료 고객당 이익을 방문자끼리 비교하는 것이 아니라 미방문자의 0원까지 포함한다. 배정된 고객, 분석에 남은 고객, 나중에 적용할 고객을 별도로 적는다.</p><p>구조 점검과 통계 점검은 다르다. 공유 용량 간섭, 실제 원가와 원장 감사는 구현하지 않았고 개인 독립을 가정했다. 현실에서 이 전제가 깨지면 비교 단위와 설계로 되돌아간다.</p><p><strong>필수 출력:</strong> A/B 비교 명세와 해석 가능한 범위. “비교 가능”은 “B가 이겼다”가 아니다.</p>''','output':'비교 명세와 증거 제한'},
{'title':'V2: 전체 평균을 누구에게 옮길 수 있는가?','body':'<p class="muted">Vector Segmentation / 고객 상태별 효과와 적용 범위를 검토합니다. 특정 임베딩이나 군집 알고리즘을 뜻하지 않습니다. 모든 실험의 집단별 심화 분석을 의무화하지 않고 기본은 배정, 분석, 적용 대상의 일치 여부를 적는 것입니다.</p>'+groups+f'''<p>같은 쿠폰이 현재 두 상태에서 다르게 보인다. 두 효과 차이를 직접 계산한 탐색 대비는 {won(r['exploratory_interaction']['effect_B_minus_A_KRW'])}, 95% 구간 {ci(r['exploratory_interaction']['ci95_KRW'])}다. “한 집단만 유의하다”는 비교를 대신 쓰지 않았다.</p><p>그러나 이 결과를 “첫 이용 대상 B가 검증된 승자”로 바꾸지는 않는다. 주지표의 현재 대상 구성은 상태별 절반이고, 집단 분석은 다중성 확증이 아닌 진단이다. 첫 이용 대상만 B를 받는 정책은 전체 대상의 A/B와 다른 질문이다.</p><p>가능한 설명은 상태별 가격 반응, 원래 방문할 고객에게 지급한 할인 비용, 방문 시점의 이동 등이다. 현재 표만으로 행동 기제를 고르거나 개인별 자연 방문 여부를 알 수는 없다.</p><p><strong>필수 출력:</strong> 현재 전체 대상에는 B 미확대, 첫 이용 대상은 새 코호트의 후속 검증 후보라는 적용 범위 문장.</p>''','output':'배정, 분석, 적용 모집단을 구분한 문장'},
{'title':'V3: 실험의 결론과 실행 결정을 따로 쓴다','body':f'''<p class="muted">Value-Linked Decision / 실험 목적의 지표와 보호 조건을 실제 선택에 연결합니다. 모든 A/B 테스트에 금전 환산이나 이익 주지표를 강제하는 것은 아닙니다.</p><table><thead><tr><th>판단</th><th>이번 기록</th></tr></thead><tbody><tr><td>주지표의 B 우위</td><td>지지하지 않음. 고정 원가 모형 아래 이익 감소를 지지.</td></tr><tr><td>최소 사업 가치</td><td>현재 전체 대상에서 예시 기준 +{plan['business_minimum_KRW_per_assigned_customer']:,}원 미충족.</td></tr><tr><td>보호 조건</td><td>철회 비열등성 미확인. 안전이나 확정 위해로 바꾸지 않음.</td></tr><tr><td>새 대상 적용</td><td>첫 이용 대상의 긍정 신호는 탐색. 혼합 정책과 장기 효과는 미검증.</td></tr><tr><td>현재 선택</td><td>전체 B 확대 거절 제안, A 유지 검토와 새 코호트 실험 준비. 실제 승인 아님.</td></tr></tbody></table><p>주지표 실패를 클릭이나 방문 수로 바꾸어 성공이라고 쓰지 않는다. 전체 실패를 지우기 위해 좋은 집단만 골라 원래 목표였다고 바꾸지도 않는다. 결과를 본 뒤 보호 한계를 느슨하게 고쳐 통과시키지 않는다.</p><p>새 실험은 첫 이용 대상의 고객당 공헌이익을 질문으로 삼고, 표본과 기간, 철회 한계 및 비용과 용량을 새로 확정한다. 표본 수와 종료 기준은 계산해야 할 작업으로 남기며 지금 임의로 제시하지 않는다.</p><p><strong>필수 출력:</strong> 선택, 근거, 미확인, 승인 책임과 다음 확인 조건을 담은 결정 기록.</p>''','output':'실험 결론과 채택이 분리된 결정 기록'}]
intro=f'''<h2>기업에서 충분히 고민할 만한 문제</h2><p>가상 자동차 서비스 사업자 JH Motors Service는 선택적 유상 서비스의 재방문을 늘리려 한다. 마케팅 팀은 1만원 쿠폰을, 재무 팀은 할인 누수를, 센터 운영자는 처리 용량을 걱정한다. 첫 이용 대상과 기존 고객에게 같은 혜택을 줄지도 논쟁이다.</p><p>현대자동차의 공식 서비스 검색과 예약 채널은 공개 맥락으로만 참고했다. 이 회사의 실제 쿠폰 실험이나 내부 문제가 있었다는 주장이 아니다. 아래 데이터와 비용은 새로 만든 교육용 고정 입력이며 기존 시승 실습과 합치지 않는다.</p><div class="contract"><strong>같은 명세로 비교</strong><br>A: 같은 안내, 쿠폰 없음 / B: 같은 안내 + 1만원 쿠폰<br>주지표: 모든 배정 고객의 30일 공헌이익<br>모형 가정: 완료당 할인 전 공헌이익 4만원, B는 쿠폰 1만원 차감. 미방문은 0원.<br>안전과 법적 고지는 모두에게 제공. 선택적 마케팅만 비교.</div>'''+facts+f'''<p><strong>눈에 띄는 숫자:</strong> B 완료는 이번 표본에서 {r['changes']['additional_completed_B_minus_A']:,}명 더 많지만 합계 공헌이익은 {won(r['changes']['total_contribution_B_minus_A_KRW'])}다. 방문 건수의 관측 순위와 방문 우위 확증은 다르다.</p><p class="caution">가상 이야기의 계획 순서를 보여주는 자료다. 작성자가 고정 결과를 설계했으므로 실제 기업의 사전등록, 실제 원가 추정, 현장 성과나 학습 효과의 증거가 아니다.</p>'''
conclusion='''<h2>무엇이 실제로 달라졌는가?</h2><table><thead><tr><th>비교</th><th>PDCA의 A/B 적용안</th><th>TRI-V의 A/B 전용안</th></tr></thead><tbody><tr><td>중심 질문</td><td>어떻게 설계하고 실행하고 검토해 다음 실험으로 이어갈까?</td><td>이 배정으로 무엇을 추정하고 어느 대상에 어떤 결정을 내릴 수 있을까?</td></tr><tr><td>강점</td><td>계약, 실행 책임, 관찰과 개선 사이클의 누락을 줄이도록 조직</td><td>분모 변경, 사후 지표 교체, 집단 선택, 승리와 채택의 혼동을 명시적으로 경계</td></tr><tr><td>약점</td><td>원형만으로는 A/B 추정 대상과 통계 절차가 구체화되지 않음. 이번 계약은 적용 제안.</td><td>세 질문만 붙이면 구호에 그침. 배정과 관측, 분석 계획과 기록을 반드시 구체화해야 함.</td></tr><tr><td>이번 결론</td><td>전체 쿠폰 확대 거절, 첫 이용 대상 새 실험 준비</td><td>동일한 결론. 지지 범위와 금지할 해석을 더 세밀하게 기록</td></tr></tbody></table><p><strong>정상적으로 수행한 PDCA도 이 잘못된 확대를 막을 수 있다.</strong> PDCA는 실패하고 TRI-V만 성공하는 사례로 꾸미지 않았다. 이번 비교는 어느 방법이 우월하다는 실험이 아니라 같은 근거를 서로 다르게 조직해 보는 예시다.</p><p>방법론을 A/B 전용으로 만들려면 “세 질문”보다 더 나아가야 한다. 결과 전에 대비와 추정 대상, 배정과 분석 단위, 지표와 분모, 관측과 종료, 집단과 다중성, 보호 및 판단 기준을 기록하게 하고, 실험 후 그 계약과 어긋난 결론을 명시적으로 막아야 한다.</p><p>두 독립된 이론을 독자에게 외우게 하기보다는 PDCA의 운영 순환 안에서 TRI-V의 검토 질문을 사용하는 구성이 이번 권장안이다. 단, 두 체계가 일대일 대응하거나 통계적 능력이 새로 생긴다는 뜻은 아니다. 저자 방법론의 명칭은 유지하고 이번 A/B 전용 계약과 출력은 아직 제안으로 둔다.</p>'''
css='''*{box-sizing:border-box}body{margin:0;background:#FFFFFF;color:#142D32;font:18px/1.7 "Malgun Gothic","Apple SD Gothic Neo",sans-serif}main{max-width:1050px;padding:28px}h1{font-size:31px;line-height:1.35;margin:0 0 10px;letter-spacing:-.04em}h2{font-size:24px;line-height:1.45;margin:22px 0 12px}p{margin:12px 0}small,.muted{color:#4F625F}small{font-size:16px}.nav,.steps{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}button{min-height:46px;padding:8px 13px;border:1px solid #4F625F;background:white;color:#142D32;border-radius:5px;font:inherit;cursor:pointer}button[aria-pressed=true]{background:#142D32;color:white}button:focus-visible,a:focus-visible{outline:3px solid #142D32;outline-offset:3px}.contract,.caution{padding:14px 18px;background:#F2F5F1}.caution{font-size:16px;color:#4F625F}.pane[hidden]{display:none}table{width:100%;border-collapse:collapse;margin:20px 0;font-size:17px;line-height:1.6}th,td{text-align:left;vertical-align:top;padding:10px 9px;border-bottom:1px solid #9CAEA6;overflow-wrap:anywhere}th{background:#F2F5F1}.map{border-top:1px solid #9CAEA6;border-bottom:1px solid #9CAEA6;padding:13px 0;font-size:19px}.steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}#triv .steps{grid-template-columns:repeat(3,minmax(0,1fr))}#triv .steps button:not(:last-child)::after{content:'↔'}.steps button{position:relative;text-align:left;min-width:0;min-height:104px}.steps small{display:block;font-size:16px}.steps button[aria-pressed=true] small{color:white}.steps button:not(:last-child)::after{content:'→';position:absolute;right:-18px;top:36px;color:#142D32}.detail{margin-top:15px}.output{font-weight:bold;padding:12px 0;border-top:1px solid #9CAEA6}.sources{border-top:1px solid #9CAEA6;margin-top:25px;padding-top:14px;font-size:16px}.sources a{color:#142D32}@media(max-width:650px){.steps,#triv .steps{grid-template-columns:1fr}.steps button{min-height:80px}#triv .steps button:not(:last-child)::after{content:'↕'}.steps button:not(:last-child)::after{content:'↓';right:50%;top:auto;bottom:-18px;font-size:18px;line-height:18px}main{padding:18px}h1{font-size:25px}h2{font-size:22px}table{font-size:16px}th,td{padding:8px 5px}.map{font-size:17px}}@media print{body{font-size:12pt}main{padding:0;max-width:none}.nav,.steps{display:none}.pane[hidden],.detail[hidden]{display:block}.pane{break-before:page}.pane:first-of-type{break-before:auto}table,.caution,.sources,small{font-size:12pt}h1{font-size:22pt}h2{font-size:17pt}tr{break-inside:avoid}h2{break-after:avoid}p{orphans:3;widows:3}@page{size:A4;margin:15mm}}'''
nav='<nav class="nav" aria-label="문제와 방법 선택">'+''.join(f'<button data-view="{k}" aria-pressed="{str(i==0).lower()}">{label}</button>' for i,(k,label) in enumerate([('problem','같은 A/B 문제'),('pdca','PDCA로 풀기'),('triv','TRI-V로 풀기'),('conclusion','어떤 차이가 있나')]))+'</nav>'
def method_html(key,steps,labels,maptext):
 return '<section id="'+key+'" class="pane" hidden><div class="map">'+maptext+'</div><div class="steps" aria-label="방법의 과정">'+''.join(f'<button data-method="{key}" data-step="{i}" aria-pressed="{str(i==0).lower()}">{html.escape(label)}<small>{html.escape(steps[i]['output'])}</small></button>' for i,label in enumerate(labels))+'</div>'+''.join(f'<article class="detail" data-detail="{key}-{i}"'+(' hidden' if i else '')+'><h2>'+x['title']+'</h2>'+x['body']+'<div class="output">이 단계의 출력 → '+x['output']+'</div></article>' for i,x in enumerate(steps))+'</section>'
body='<main><h1>방문이 더 많아 보이면, 쿠폰을 확대해도 될까?</h1><p>A/B 테스트만을 위한 운영과 판단 절차를 같은 자료로 비교합니다.</p><small>가상 자동차 서비스 사례. 실제 제조사의 실험이나 내부 성과가 아닙니다.</small>'+nav+'<section id="problem" class="pane">'+intro+'</section>'+method_html('pdca',pdca,['Plan','Do','Check','Act'],'실험 계약 → 배정과 측정 → 증거 검토 → 현재 선택과 새 실험 ↺')+method_html('triv',triv,['V1 비교','V2 적용 대상','V3 결정'],'세 축의 기준은 실험 전에 함께 정함 / 실험 후 반복 검토하고 필요한 축으로 되돌림 ↺')+'<section id="conclusion" class="pane" hidden>'+conclusion+'</section><div class="sources"><strong>계산과 출처</strong><p>고정 입력과 합성 고객별 CSV, 계산 JSON 및 스크립트를 별도로 제공합니다. 층화 표준화와 HC2 회귀 대비를 대조했습니다. 실제 사용성이나 조직 성과를 검증한 자료는 아닙니다.</p><a href="https://asq.org/quality-resources/pdca-cycle" target="_blank" rel="noopener">ASQ의 PDCA</a> / <a href="https://www.hyundai.com/kr/ko/customer-service/service-network/service-reservation-search.html" target="_blank" rel="noopener">공식 서비스 예약 채널의 공개 맥락</a></div></main>'
script='''<script>const selected={pdca:0,triv:0};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.pane').forEach(p=>p.hidden=p.id!==b.dataset.view);document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{let k=b.dataset.method,i=Number(b.dataset.step);selected[k]=i;document.querySelectorAll('#'+k+' .detail').forEach((x,j)=>x.hidden=j!==i);document.querySelectorAll('[data-method="'+k+'"]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});</script>'''
(D/'walkthrough.html').write_text('<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A/B 전용 PDCA와 TRI-V 사례</title><style>'+css+'</style></head><body>'+body+script+'</body></html>',encoding='utf-8')
md='# A/B 전용 PDCA와 TRI-V: 같은 문제를 끝까지 풀기\n\n실제 기업의 실적이 아닌 교육용 고정 입력이다. 실험 전이라는 말은 가상 이야기의 순서이며 실제 사전등록이 아니다.\n\n'
import re
def table_markdown(match):
 rows=[]
 for tr in re.findall(r'<tr>(.*?)</tr>',match.group(0),re.S):
  cells=re.findall(r'<t[hd][^>]*>(.*?)</t[hd]>',tr,re.S)
  rows.append([re.sub('<[^>]*>','',re.sub(r'<br\s*/?>',' / ',c)).strip() for c in cells])
 if not rows:return ''
 lines=['| '+' | '.join(rows[0])+' |','| '+' | '.join(['---']*len(rows[0]))+' |']
 lines.extend('| '+' | '.join(row)+' |' for row in rows[1:])
 return '\n\n'+'\n'.join(lines)+'\n\n'
for section,items in [('기업 문제',[{'title':'쿠폰은 방문과 이익을 함께 개선하는가','body':intro}]),('PDCA의 A/B 적용안',pdca),('TRI-V의 A/B 전용안',triv),('정직한 비교',[{'title':'두 방식의 역할과 한계','body':conclusion}])]:
 md+='\n## '+section+'\n\n'
 for x in items:
  plain=re.sub(r'<table>.*?</table>',table_markdown,x['body'],flags=re.S);plain=re.sub(r'</(?:p|tr|h2)>','\n\n',plain);plain=re.sub(r'<br\s*/?>',' / ',plain);plain=re.sub('<[^>]*>','',plain)
  md+='### '+x['title']+'\n\n'+html.unescape(plain)+'\n\n'
md+='\n원자료와 계산은 design_fixture.json, customer_fixture.csv, calculated_results.json, scripts/analyze_ab_only_methods_v01.py를 따른다. 이 별도 검토 자료의 소제목은 전자책 본문의 문단별 소제목이 아니며 본책을 자동 개정하지 않았다.\n'
md='\n'.join(line.rstrip() for line in md.splitlines())+'\n'
(D/'WALKTHROUGH.md').write_text(md,encoding='utf-8');print(json.dumps({'html':str(D/'walkthrough.html'),'markdown':str(D/'WALKTHROUGH.md'),'pdca_steps':len(pdca),'tri_v_axes':len(triv),'same_case':True,'book_changed':False},ensure_ascii=False,indent=2))
